class XMLDocumentBuilder {

    // Function to create a DocumentBuilder with namespace awareness
    DocumentBuilder createDocumentBuilder(boolean isNamespaceAware) throws ParserConfigurationException {
        DocumentBuilderFactory builderFactory = createDocumentBuilderFactory(isNamespaceAware);
        return builderFactory.newDocumentBuilder();
    }

    // Function to create a DocumentBuilderFactory with namespace awareness
    private DocumentBuilderFactory createDocumentBuilderFactory(boolean isNamespaceAware) {
        DocumentBuilderFactory builderFactory = DocumentBuilderFactory.newInstance();
        builderFactory.setNamespaceAware(isNamespaceAware);
        return builderFactory;
    }
}

