        // Check that the output does not contain the sensitive keyword
        String output = outContent.toString();
        assertFalse(output.contains("Sensitive Data"));
        assertFalse(output.contains("API_KEY"));

        // Restore the original System.out
        System.setOut(originalOut);
    }

    // Test 2: Controlled Exception Handling
    @Test
    void testControlledExceptionHandling() {
        Exception npe = new NullPointerException("null pointer");

        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outContent));

        errorHandling.handleException(npe);

        String output = outContent.toString();
        assertTrue(output.contains("Exception"));

        // Restore the original System.out
        System.setOut(originalOut);
    }

