    }

    // Test getProperty method when property is not set
    @Test
    void testGetPropertyNotSet() {
        SystemPropertiesHandler handler = new SystemPropertiesHandler();

        // Retrieve a property that is not set
        String result = handler.getProperty("unset.property");

        // Assert the result is null since the property does not exist
        assertNull(result);
    }

    // Test checkOSSupport method with "Windows 95"
    @Test
    void testCheckOSSupportWindows95() {
        SystemPropertiesHandler handler = new SystemPropertiesHandler();

        // Capture console output
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        PrintStream printStream = new PrintStream(output);
        PrintStream originalOut = System.out;
        System.setOut(printStream);

        try {
            // Check for unsupported OS, Windows 95
            handler.checkOSSupport("Windows 95");

            // Assert that "Not supported" was printed
            assertEquals("Not supported" + System.lineSeparator(), output.toString());
        } finally {
            // Reset console output
            System.setOut(originalOut);
        }
    }

    // Test checkOSSupport method with another OS
