import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class SystemPropertiesHandlerTest {

    SystemPropertiesHandler handler;

    @BeforeEach
    void setUp() {
        handler = new SystemPropertiesHandler();
    }

    @Test
    void testClearPropertyNull() {
        assertDoesNotThrow(() -> handler.clearProperty(null));
    }

    @Test
    void testClearPropertySuccess() {
        System.setProperty("test.property", "value");
        handler.clearProperty("test.property");
        assertNull(System.getProperty("test.property"));
    }

    @Test
    void testClearNonExistentProperty() {
        assertDoesNotThrow(() -> handler.clearProperty("non.existent.property"));
    }

    @Test
    void testGetExistingProperty() {
        String osName = System.getProperty("os.name");
        assertEquals(osName, handler.getProperty("os.name"));
    }

    @Test
    void testGetNonExistentProperty() {
        assertNull(handler.getProperty("non.existent.property"));
    }

    @Test
    void testGetPropertyNull() {
        assertDoesNotThrow(() -> handler.getProperty(null));
    }

    @Test
    void testUnsupportedOS() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outContent));

        handler.checkOSSupport("Windows 95");

        assertTrue(outContent.toString().trim().contains("Not supported"));

        System.setOut(originalOut);
    }

    @Test
    void testSupportedOS() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outContent));

        handler.checkOSSupport("Linux");

        assertEquals("", outContent.toString().trim());

        System.setOut(originalOut);
    }

    @Test
    void testOSSupportCaseSensitivity() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outContent));

        handler.checkOSSupport("WINDOWS 95");

        assertTrue(outContent.toString().trim().contains("Not supported"));

        System.setOut(originalOut);
    }

    @Test
    void testCheckOSSupportNull() {
        assertDoesNotThrow(() -> handler.checkOSSupport(null));
    }

    @Test
    void testConcurrency() {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable clearTask = () -> handler.clearProperty("concurrent.property");
        Runnable getTask = () -> handler.getProperty("concurrent.property");

        executor.submit(clearTask);
        executor.submit(getTask);

        executor.shutdown();
        assertDoesNotThrow(() -> executor.awaitTermination(5, TimeUnit.SECONDS));
    }

    @Test
    void testMaliciousInput() {
        assertDoesNotThrow(() -> handler.clearProperty("; DROP TABLE users;"));
        assertDoesNotThrow(() -> handler.getProperty("1 OR 1=1"));
        assertDoesNotThrow(() -> handler.checkOSSupport("$(rm -rf /)"));
    }

    @Test
    void testBoundaryConditions() {
        String longString = "a".repeat(10000);
        assertDoesNotThrow(() -> handler.clearProperty(longString));
        assertDoesNotThrow(() -> handler.getProperty(longString));
        assertDoesNotThrow(() -> handler.checkOSSupport(longString));
    }
}

