import java.util.Properties;
import java.io.FileInputStream;
import java.sql.DriverManager;
import java.sql.Connection;

class DatabaseConnection {

    public static Connection connectToDatabase(String configFilePath, String url, String usr) throws Exception {
        Properties prop = loadProperties(configFilePath);
        String password = prop.getProperty("password");
        return DriverManager.getConnection(url, usr, password);
    }

    private static Properties loadProperties(String configFilePath) throws Exception {
        Properties prop = new Properties();
        prop.load(new FileInputStream(configFilePath));
        return prop;
    }
}

