        byte[] storedHash = hashingClass.calculateHash(userInput);

        // Mocking the equal method to return true for testing purposes
        Hashing spyHashing = spy(hashingClass);
        doReturn(true).when(spyHashing).equal(any(byte[].class), any(byte[].class));

