        byte[] userInput = "wrongPassword".getBytes();
        byte[] storedHash = hashingClass.calculateHash("password".getBytes());

        // Mocking the equal method to return false for testing purposes
        Hashing spyHashing = spy(hashingClass);
        doReturn(false).when(spyHashing).equal(any(byte[].class), any(byte[].class));

