class HashingSecurityTests {

    private Hashing hashing;

    @BeforeEach
    void setUp() {
        hashing = new Hashing();
    }

    // Hash Collision Test
    @Test
    void testHashCollision() {
        byte[] input1 = "input1".getBytes();
        byte[] input2 = "input2".getBytes();

        try {
            byte[] hash1 = hashing.calculateHash(input1);
            byte[] hash2 = hashing.calculateHash(input2);

            assertNotEquals(new String(hash1), new String(hash2), "Hashes should not match for different inputs.");
        } catch (Exception e) {
            fail("Exception thrown in testHashCollision: " + e.getMessage());
        }
    }

    // Preimage Attack Test
    @Test
    void testPreimageAttack() {
        byte[] input = "knownInput".getBytes();

        try {
            byte[] hash = hashing.calculateHash(input);

            // Here, ensure there’s no way to deduce original input from the hash
            assertNotEquals("knownInput", new String(hash), "Original input should not be derivable from the hash.");
        } catch (Exception e) {
            fail("Exception thrown in testPreimageAttack: " + e.getMessage());
        }
    }

    // Second Preimage Attack Test
    @Test
    void testSecondPreimageAttack() {
        byte[] input = "someInput".getBytes();

        try {
            byte[] hash = hashing.calculateHash(input);
            byte[] differentInput = "differentInput".getBytes();
            byte[] differentHash = hashing.calculateHash(differentInput);

            // Ensure no other input generates the same hash
            assertNotEquals(new String(hash), new String(differentHash), "Different inputs should not produce identical hashes.");
        } catch (Exception e) {
            fail("Exception thrown in testSecondPreimageAttack: " + e.getMessage());
        }
    }

    // Resistance to Birthday Attack
    @Test
    void testBirthdayAttackResistance() {
        byte[] input1 = "uniqueInput1".getBytes();
        byte[] input2 = "uniqueInput2".getBytes();

        try {
            byte[] hash1 = hashing.calculateHash(input1);
            byte[] hash2 = hashing.calculateHash(input2);

            assertNotEquals(new String(hash1), new String(hash2), "Hashes should differ for different inputs.");
        } catch (Exception e) {
            fail("Exception thrown in testBirthdayAttackResistance: " + e.getMessage());
        }
    }

    // Secure Hash Algorithm Utilization
    @Test
    void testSecureHashAlgorithm() {
        byte[] input = "secureHashTest".getBytes();

        try {
            byte[] hash = hashing.calculateHash(input);

            // Assuming SHA-256 results in a specific length
            assertEquals(32, hash.length, "SHA-256 hash should be 32 bytes long.");
        } catch (Exception e) {
            fail("Exception thrown in testSecureHashAlgorithm: " + e.getMessage());
        }
    }

    // Equality Check Validation
    @Test
    void testEqualityCheck() {
        byte[] input = "testInput".getBytes();

        try {
            byte[] hash = hashing.calculateHash(input);

            assertTrue(hashing.equal(hash, hash), "The equality method should return true for identical hashes.");
        } catch (Exception e) {
            fail("Exception thrown in testEqualityCheck: " + e.getMessage());
        }
    }

    // Exception Handling Robustness
    @Test
    void testExceptionHandling() {
        byte[] invalidInput = null;

        assertThrows(Exception.class, () -> {
            hashing.calculateHash(invalidInput);
        }, "Exception should be thrown for null inputs.");
    }

    // Password Storage Security
    @Test
    void testPasswordStorageSecurity() {
        byte[] password1 = "password".getBytes();
        byte[] password2 = "password".getBytes();

        try {
            byte[] hash1 = hashing.calculateHash(password1);
            byte[] hash2 = hashing.calculateHash(password2);

            assertNotEquals(new String(hash1), new String(hash2), "Same passwords should produce different hashes with salting.");
        } catch (Exception e) {
            fail("Exception thrown in testPasswordStorageSecurity: " + e.getMessage());
        }
    }

    // Concurrency and Race Conditions
    @Test
    void testConcurrency() {
        byte[] input = "concurrentInput".getBytes();

        try {
            byte[] hash = hashing.calculateHash(input);

            for (int i = 0; i < 10; i++) {
                new Thread(() -> {
                    try {
                        byte[] concurrentHash = hashing.calculateHash(input);
                        assertEquals(new String(hash), new String(concurrentHash), "Concurrent hashes should match.");
                    } catch (Exception e) {
                        fail("Exception thrown in thread of testConcurrency: " + e.getMessage());
                    }
                }).start();
            }
        } catch (Exception e) {
            fail("Exception thrown in testConcurrency: " + e.getMessage());
        }
    }

    // Input Encoding Issues
    @Test
    void testInputEncoding() {
        byte[] input1 = "inputÄÖÜ".getBytes();
        byte[] input2 = "inputäöü".getBytes();

        try {
            byte[] hash1 = hashing.calculateHash(input1);
            byte[] hash2 = hashing.calculateHash(input2);

            assertNotEquals(new String(hash1), new String(hash2), "Hashes should differ for differently encoded inputs.");
        } catch (Exception e) {
