        for (int i = 0; i < THREAD_COUNT; i++) {
            executor.execute(() -> {
                account.deposit(10.0);
                account.withdraw(10.0);
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);

        assertEquals(1000.0, account.getBalance());
    }

