import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class BankAccount {

    // Core variables
    private double balance;
    private ReentrantLock balanceChangeLock;
    private Condition sufficientFundsCondition;

    // Constructor to initialize the lock and condition
    public BankAccount(double initialBalance) {
        this.balance = initialBalance;
        this.balanceChangeLock = new ReentrantLock();
        this.sufficientFundsCondition = balanceChangeLock.newCondition();
    }

    // Method to deposit amount into BankAccount
    public void deposit(double amount) {
        balanceChangeLock.lock(); // Set lock to block access to BankAccount from other threads
        try {
            double newBalance = balance + amount;
            balance = newBalance;
            sufficientFundsCondition.signalAll(); // Inform other threads that funds are available
        } catch (Exception e) {
            // Handle exception if needed
        } finally {
            balanceChangeLock.unlock(); // Unlock lock object
        }
    }

    // Method to withdraw amount from bank account
    public void withdraw(double amount) {
        balanceChangeLock.lock(); // Set lock to block access to BankAccount from other threads
        try {
            while (balance < amount) {
                sufficientFundsCondition.await(); // Temporarily unblock access until sufficient funds are available
            }
            double newBalance = balance - amount;
            balance = newBalance;
        } catch (Exception e) {
            // Handle exception if needed
        } finally {
            balanceChangeLock.unlock(); // Unlock lock object
        }
    }

    // Getter for balance to facilitate testing
    public double getBalance() {
        return balance;
    }

    // Setter for balance to facilitate testing
    public void setBalance(double balance) {
        this.balance = balance;
    }
}

