import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.*;

class CloneableUtilityTest {

    // Verify Cloning Restriction
    @Test
    void testAttemptCloneThrowsException() {
        CloneableUtility utility = new CloneableUtility();
        assertThrows(CloneNotSupportedException.class, utility::attemptClone);
    }

    // Class Introspection
    @Test
    void testDoesNotImplementCloneable() {
        Class<?> clazz = CloneableUtility.class;
        boolean implementsCloneable = Cloneable.class.isAssignableFrom(clazz);
        assertFalse(implementsCloneable, "Class should not implement Cloneable");
    }

    // Sensitive Data Access (Simulated)
    @Test
    void testSensitiveDataInaccessible() throws Exception {
        CloneableUtility utility = new CloneableUtility();

        // Use reflection to attempt cloning, which should not succeed
        Method method = CloneableUtility.class.getDeclaredMethod("cloneHelper");
        method.setAccessible(true);

        assertThrows(CloneNotSupportedException.class, () -> method.invoke(utility));
    }

    // Reflection-based Cloning Attempt
    @Test
    void testReflectionDoesNotAllowClone() throws Exception {
        CloneableUtility utility = new CloneableUtility();

        Method cloneMethod = Object.class.getDeclaredMethod("clone");
        cloneMethod.setAccessible(true);

        assertThrows(IllegalAccessException.class, () -> cloneMethod.invoke(utility));
    }

    // Subclass Safety
    @Test
    void testSubclassCannotBypassRestrictions() {
        class CloneableUtilitySubclass extends CloneableUtility {}

        CloneableUtilitySubclass subclassInstance = new CloneableUtilitySubclass();

        assertThrows(CloneNotSupportedException.class, subclassInstance::attemptClone);
    }

    // Access Control
    @Test
    void testOnlyAttemptCloneIsPublic() {
        Method[] methods = CloneableUtility.class.getDeclaredMethods();
        for (Method method : methods) {
            boolean isPublic = Modifier.isPublic(method.getModifiers());
            if (method.getName().equals("attemptClone")) {
                assertTrue(isPublic, "attemptClone should be public");
            } else {
                assertFalse(isPublic, method.getName() + " should not be public");
            }
        }
    }

    // Concurrency and Synchronization
    @Test
    void testConcurrencyDoesNotAffectBehavior() {
        CloneableUtility utility = new CloneableUtility();

        Runnable cloneAttempt = () -> {
            assertThrows(CloneNotSupportedException.class, utility::attemptClone);
        };

        Thread thread1 = new Thread(cloneAttempt);
        Thread thread2 = new Thread(cloneAttempt);

        thread1.start();
        thread2.start();

        assertDoesNotThrow(() -> {
            thread1.join();
            thread2.join();
        });
    }
}

