import java.io.OutputStream;
import java.util.Properties;

class FileExecutor {
    // Method to read from a file and print its content
    void executeFileOperation(Properties cfg, OutputStream out, byte[] arr) throws IOException {
        String filename = cfg.getProperty("sub") + ".txt";
        fisOperation(filename, out, arr);
    }

    // Abstracted function to handle file operations
    private void fisOperation(String filename, OutputStream out, byte[] arr) throws IOException {
        FileInputStream fis = new FileInputStream(filename);
        int amt = fis.read(arr);
        out.write(arr, 0, amt);
    }
}

