    boolean isAuthenticatedCookiePresent(Cookie[] cookies) {
        boolean authenticated = false;
        Cookie c;

        for (int i = 0; i < cookies.length; i++) {
            c = cookies[i];
            if (isAuthenticatedCookie(c)) {
                authenticated = true;
            }
        }
        return authenticated;
    }

    // Helper method to determine if a cookie signifies authentication
    boolean isAuthenticatedCookie(Cookie cookie) {
        return cookie.getName().equals("authenticated") && Boolean.TRUE.equals(cookie.getValue());
    }
