import java.io.FileInputStream;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;
import java.util.Base64;

class DatabaseUtil {

    // Abstracted function for setting up database connection
    public static Connection setupConnection(String url, String usr, String propertiesFilePath) throws IOException, SQLException {
        Properties prop = new Properties();
        prop.load(new FileInputStream(propertiesFilePath));

        // Decode the password
        String password = new String(Base64.getDecoder().decode(prop.getProperty("password")));

        // Establish the connection
        return DriverManager.getConnection(url, usr, password);
    }
}

