    }

    @Test
    void testExecutePrivilegedAction_LibraryLoaded() {
        // Mock AccessController to simulate successful library loading
        PrivilegedAction<Object> action = mock(PrivilegedAction.class);

        when(action.run()).thenReturn(null);

        // Execute and assert
        assertDoesNotThrow(() -> {
            Object result = AccessController.doPrivileged(action);
            assertNull(result);
        });
    }

    @Test
    void testExecutePrivilegedAction_UnsatisfiedLinkError() {
        // Mock PrivilegedAction to simulate UnsatisfiedLinkError
        PrivilegedAction<Object> action = () -> {
            throw new UnsatisfiedLinkError("No awt library in java.library.path");
        };

        UnsatisfiedLinkError thrown = assertThrows(UnsatisfiedLinkError.class, () -> {
            AccessController.doPrivileged(action);
        });

        assertEquals("No awt library in java.library.path", thrown.getMessage());
    }

    @Test
    void testExecutePrivilegedAction_SecurityException() {
        // Set a SecurityManager to simulate security restriction
        System.setSecurityManager(new SecurityManager() {
            @Override
            public void checkPermission(java.security.Permission perm) {
                if (perm.getName().contains("loadLibrary.awt")) {
                    throw new SecurityException("Permission denied: " + perm.getName());
                }
            }
        });

        SecurityException thrown = assertThrows(SecurityException.class, () -> {
            PrivilegedAction<Object> action = () -> {
                System.loadLibrary("awt");
                return null;
            };
            AccessController.doPrivileged(action);
        });

        assertTrue(thrown.getMessage().contains("Permission denied"));
    }
}

