    }

    @Test
    void testPredictableOutputWithSameSeed() {
        int result1 = generator.generateAccountID(1234567890L);
        int result2 = generator.generateAccountID(1234567890L);
        assertEquals(result1, result2, "IDs should be the same for the same seed.");
    }

    @Test
    void testPredictablePatternsWithConsecutiveSeeds() {
        int result1 = generator.generateAccountID(123456789L);
        int result2 = generator.generateAccountID(123456790L);
        assertNotEquals(result1, result2, "IDs should differ for consecutive seeds if there's randomness.");
    }

    @Test
    void testCommonSeedValues() {
        assertDoesNotThrow(() -> {
            generator.generateAccountID(0L);
            generator.generateAccountID(1L);
            generator.generateAccountID(Long.MAX_VALUE);
            generator.generateAccountID(Long.MIN_VALUE);
        }, "Method should handle common and edge seeds.");
    }

    @Test
    void testNegativeSeeds() {
        int result1 = generator.generateAccountID(-123456789L);
        int result2 = generator.generateAccountID(-987654321L);
        assertNotEquals(result1, result2, "IDs should differ for different negative seeds.");
    }

    @Test
