            arg.setAddress(validPacket.getAddress());
            arg.setPort(validPacket.getPort());
            return null;
        }).when(mockSocket).receive(any(DatagramPacket.class));

        // Run handlePackets
        handler.handlePackets(buffer, mockSocket, secret, expectedHostName, expectedInput);

        // Verify response packet is sent
        verify(mockSocket, times(1)).send(argThat(packet -> {
            return new String(packet.getData(), 0, packet.getLength()).equals(secret) &&
