import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;

class FileReaderUtility {

    // Main function to abstract file reading
    public String readFile(String filename) throws FileNotFoundException, IOException, Exception {
        return readFromFile(filename);
    }

    // Function to read from file and handle exceptions
    private String readFromFile(String filename) throws FileNotFoundException, IOException, Exception {
        String retString = null;
        try {
            File file = initializeFile(filename);
            char[] cBuf = initializeBuffer(file);
            retString = readDataFromFile(file, cBuf);
        } catch (FileNotFoundException ex) {
            handleFileNotFoundException(filename, ex);
        } catch (IOException ex) {
            handleIOException(ex);
        } catch (Exception ex) {
            handleGeneralException(ex);
        }
        return retString;
    }

    // Helper function to initialize the File object
    private File initializeFile(String filename) {
        return new File(filename);
    }

    // Helper function to initialize character buffer
    private char[] initializeBuffer(File file) {
        long fLen = file.length();
        return new char[(int) fLen];
    }

    // Helper function to read data from file
    private String readDataFromFile(File file, char[] cBuf) throws IOException {
        FileReader fr = new FileReader(file);
        fr.read(cBuf, 0, (int) file.length());
        fr.close();
        return new String(cBuf);
    }

    // Exception handling for FileNotFoundException
    private void handleFileNotFoundException(String filename, FileNotFoundException ex) throws FileNotFoundException {
        System.err.println("Error: FileNotFoundException opening the input file: " + filename);
        System.err.println("" + ex.getMessage());
        throw new FileNotFoundException(ex.getMessage());
    }

    // Exception handling for IOException
    private void handleIOException(IOException ex) throws IOException {
        System.err.println("Error: IOException reading the input file.\n" + ex.getMessage());
        throw new IOException(ex);
    }

    // Exception handling for general Exception
    private void handleGeneralException(Exception ex) throws Exception {
        System.err.println("Error: Exception reading the input file.\n" + ex.getMessage());
        throw new Exception(ex);
