        customer.setName("Mike");
        assertEquals("Mike", customer.getName(), "Customer name should be updated to Mike");
    }

    @Test
    void testSetAge() {
        Customer customer = new Customer("John", 25, "john@example.com");
        customer.setAge(35);
        assertEquals(35, customer.getAge(), "Customer age should be updated to 35");
    }

    @Test
    void testSetEmail() {
        Customer customer = new Customer("John", 25, "john@example.com");
        customer.setEmail("john.new@example.com");
        assertEquals("john.new@example.com", customer.getEmail(), "Customer email should be updated");
    }

    @Test
    void testIsAdult() {
        Customer customer = new Customer("John", 25, "john@example.com");
        assertTrue(customer.isAdult(), "Customer should be considered an adult");

