import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class BankAccountCheckerTest {

    private BankAccountChecker checker = new BankAccountChecker();

    @Test
    void testBasicEquality() {
        // Using the correct constructor that requires only a single String parameter.
        BankAccount account1 = new BankAccount("123456");
        BankAccount account2 = new BankAccount("123456");
        assertTrue(checker.isSameAccount(account1, account2));
    }

    @Test
    void testBasicInequality() {
        BankAccount account1 = new BankAccount("123456");
        BankAccount account3 = new BankAccount("654321");
        assertFalse(checker.isSameAccount(account1, account3));
    }

    @Test
    void testSelfComparison() {
        BankAccount account1 = new BankAccount("123456");
        assertTrue(checker.isSameAccount(account1, account1));
    }

    @Test
    void testNullParameter() {
        BankAccount account1 = new BankAccount("123456");
        assertFalse(checker.isSameAccount(null, account1));
        assertFalse(checker.isSameAccount(account1, null));
        assertFalse(checker.isSameAccount(null, null));
    }

    @Test
    void testSymmetric() {
        BankAccount account1 = new BankAccount("123456");
        BankAccount account2 = new BankAccount("123456");
        assertTrue(checker.isSameAccount(account1, account2));
        assertTrue(checker.isSameAccount(account2, account1));
    }

    @Test
    void testTransitive() {
        BankAccount account1 = new BankAccount("123456");
        BankAccount account2 = new BankAccount("123456");
        BankAccount account3 = new BankAccount("123456");
        assertTrue(checker.isSameAccount(account1, account2));
        assertTrue(checker.isSameAccount(account2, account3));
        assertTrue(checker.isSameAccount(account1, account3));
    }

    @Test
    void testConsistent() {
        BankAccount account1 = new BankAccount("123456");
        BankAccount account2 = new BankAccount("123456");
        for (int i = 0; i < 10; i++) {
            assertTrue(checker.isSameAccount(account1, account2));
        }
    }

    @Test
    void testEqualsMethodOverride() {
        BankAccount account1 = new BankAccount("123456");
        BankAccount differentAccount = new BankAccount("654321");
        assertTrue(account1.equals(account1)); 
        assertFalse(account1.equals(differentAccount)); 
    }

    @Test
    void testDifferentObjectType() {
        BankAccount account1 = new BankAccount("123456");
        assertFalse(account1.equals(new Object())); // Different type
    }

    @Test
    void testEdgeCaseEmptyValues() {
        BankAccount emptyAccount1 = new BankAccount("");
        BankAccount emptyAccount2 = new BankAccount("");
        assertTrue(checker.isSameAccount(emptyAccount1, emptyAccount2));
    }
}

